async function main() {
  // Clear existing data
  const { error: delError } = await supabase.from('placements').delete().neq('id', '00000000-0000-0000-0000-000000000000')
  if (delError) console.error('Delete error:', delError.message)

  const batchSize = 10
  for (let i = 0; i < data.length; i += batchSize) {
    const batch = data.slice(i, i + batchSize)
    const { error } = await supabase.from('placements').insert(batch)
    if (error) {
      console.error(`Batch ${i}-${i+batchSize} error:`, error.message)
    } else {
      console.log(`Inserted batch ${i}-${i+batchSize} (${batch.length} rows)`)
    }
  }

  const { count } = await supabase.from('placements').select('*', { count: 'exact', head: true })
  console.log(`Total placements in database: ${count}`)
}

main().catch(console.error)
